// FUNCTION: BFME2 0x001A2260 size=91 name=?Update_On_Visibilty@ParticleEmitterClass@@MAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
void ParticleEmitterClass::Update_On_Visibilty()
{
	// Simply start or stop the emission based on the visibility state of the emitter.
	if (Is_Not_Hidden_At_All () && IsInvisible == false) {
		if (Is_Stopped () && IsInScene) {
			Start ();
			return;
		}
	}

	if (Is_Not_Hidden_At_All () == false || IsInvisible) {
		if (Is_Stopped () == false) {
			Stop ();
		}
	}
}

